-- -- [DOMESTIC_STOCK] 국내 주식 관련 퀴즈 (5개)
-- INSERT INTO quizzes (quizzes_id, quiz_topics_id, crawled_sources_id, title, question, answer_explanation, choices, main_topic, sub_topic) VALUES 
-- ('10000000-0000-0000-0000-000000000001'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, '3b0117b7-d4e4-408e-a988-0ed8dd5c0836'::uuid, '상장폐지 이해하기', '상장사가 상장 유지 조건을 충족하지 못하여 거래소에서 퇴출되는 절차를 무엇이라 하는가?', '상장폐지는 기업의 재무구조 악화나 공시 의무 위반 등이 주요 원인이 되어 거래소에서 퇴출되는 것을 말합니다.', '[{"no": 1, "content": "유상증자", "isCorrect": false}, {"no": 2, "content": "상장폐지", "isCorrect": true}, {"no": 3, "content": "기업공개", "isCorrect": false}, {"no": 4, "content": "무상감자", "isCorrect": false}]'::json, 'DOMESTIC_STOCK', '상장폐지'),
-- ('10000000-0000-0000-0000-000000000002'::uuid, '54fcf49f-b4e1-4d01-af3b-9838c00be556'::uuid, 'd20a1f27-d509-4c6d-b795-7fb9b599a26b'::uuid, '유상증자의 목적', '기업이 발행 주식 수를 늘려 자본금을 확충하는 행위를 무엇이라 하는가?', '유상증자는 기업이 실질적으로 현금을 조달하기 위해 신주를 발행하는 방법입니다.', '[{"no": 1, "content": "무상증자", "isCorrect": false}, {"no": 2, "content": "유상증자", "isCorrect": true}, {"no": 3, "content": "액면분할", "isCorrect": false}, {"no": 4, "content": "주식배당", "isCorrect": false}]'::json, 'DOMESTIC_STOCK', '유상증자'),
-- ('10000000-0000-0000-0000-000000000003'::uuid, '4fe748f4-8981-4720-9045-e0e1f0be846d'::uuid, '75cc1b11-b346-48d6-b4da-f0de6d5681f2'::uuid, '공매도 기법', '주가가 하락할 것으로 예상될 때, 주식을 빌려서 먼저 팔고 나중에 주가가 떨어지면 사서 되갚는 투자 기법은?', '하락장에서 수익을 내기 위해 사용되는 대표적인 기법으로, 비싸게 팔고 싸게 사는 것이 핵심입니다.', '[{"no": 1, "content": "직접매수", "isCorrect": false}, {"no": 2, "content": "공매도", "isCorrect": true}, {"no": 3, "content": "롱 포지션", "isCorrect": false}, {"no": 4, "content": "지정가 주문", "isCorrect": false}]'::json, 'DOMESTIC_STOCK', '공매도'),
-- ('10000000-0000-0000-0000-000000000004'::uuid, 'f3baa314-195c-4fbd-a385-abea755aa5f8'::uuid, 'cbcdb9e5-4ecf-4757-b1b5-d203cc7067fd'::uuid, '분식회계의 정의', '기업이 재무제표를 허위로 작성하여 실적을 실제보다 좋게 보이도록 속이는 행위는?', '분식회계는 회계 장부를 예쁘게 분칠한다는 뜻에서 유래했으며, 심각한 금융 범죄입니다.', '[{"no": 1, "content": "관리회계", "isCorrect": false}, {"no": 2, "content": "분식회계", "isCorrect": true}, {"no": 3, "content": "재무감사", "isCorrect": false}, {"no": 4, "content": "공시의무", "isCorrect": false}]'::json, 'DOMESTIC_STOCK', '분식회계'),
-- ('10000000-0000-0000-0000-000000000005'::uuid, '7516776b-10bd-4e9b-b727-c905598c06e7'::uuid, 'a0e786e4-08e9-4a9f-91e7-434483da523f'::uuid, '주가 변동성', '주가나 지수가 짧은 기간 동안 얼마나 크게 움직이는지를 나타내는 척도는?', '변동성(Volatility)은 수익률의 표준편차 등으로 측정하며, 시장의 불확실성을 나타냅니다.', '[{"no": 1, "content": "변동성", "isCorrect": true}, {"no": 2, "content": "유동성", "isCorrect": false}, {"no": 3, "content": "안정성", "isCorrect": false}, {"no": 4, "content": "수익성", "isCorrect": false}]'::json, 'DOMESTIC_STOCK', '변동성');

-- -- [FUTURES] 선물 및 파생상품 관련 퀴즈 (5개)
-- INSERT INTO quizzes (quizzes_id, quiz_topics_id, crawled_sources_id, title, question, answer_explanation, choices, main_topic, sub_topic) VALUES 
-- ('20000000-0000-0000-0000-000000000001'::uuid, 'b60e3b88-437f-4be4-835c-338431977cdc'::uuid, 'ae34896e-e87e-445f-b1ee-2fbac81f0c22'::uuid, '선물 롱 포지션', '선물 시장에서 기초자산의 가격이 상승할 것을 예상하고 계약을 매수하는 포지션의 명칭은?', '롱(Long) 포지션은 매수 포지션이라고도 하며, 가격 상승 시 이익을 얻습니다.', '[{"no": 1, "content": "숏(Short)", "isCorrect": false}, {"no": 2, "content": "롱(Long)", "isCorrect": true}, {"no": 3, "content": "헷지(Hedge)", "isCorrect": false}, {"no": 4, "content": "스왑(Swap)", "isCorrect": false}]'::json, 'FUTURES', '선물거래 기초'),
-- ('20000000-0000-0000-0000-000000000002'::uuid, 'b60e3b88-437f-4be4-835c-338431977cdc'::uuid, 'ae34896e-e87e-445f-b1ee-2fbac81f0c22'::uuid, '선물 숏 포지션', '선물 시장에서 기초자산의 가격이 하락할 것을 예상하고 계약을 매도하는 포지션의 명칭은?', '숏(Short) 포지션은 매도 포지션이라고도 하며, 가격 하락 시 이익을 얻습니다.', '[{"no": 1, "content": "롱(Long)", "isCorrect": false}, {"no": 2, "content": "숏(Short)", "isCorrect": true}, {"no": 3, "content": "레버리지", "isCorrect": false}, {"no": 4, "content": "옵션", "isCorrect": false}]'::json, 'FUTURES', '선물거래 기초'),
-- ('20000000-0000-0000-0000-000000000003'::uuid, 'b60e3b88-437f-4be4-835c-338431977cdc'::uuid, 'ae34896e-e87e-445f-b1ee-2fbac81f0c22'::uuid, '파생상품의 본질', '기초자산의 가치 변동에 따라 가격이 결정되는 금융 상품을 무엇이라 하는가?', '파생상품은 선물, 옵션, 스왑 등을 포함하는 상위 개념입니다.', '[{"no": 1, "content": "우량주", "isCorrect": false}, {"no": 2, "content": "파생상품", "isCorrect": true}, {"no": 3, "content": "수익증권", "isCorrect": false}, {"no": 4, "content": "지수펀드", "isCorrect": false}]'::json, 'FUTURES', '파생상품'),
-- ('20000000-0000-0000-0000-000000000004'::uuid, 'b60e3b88-437f-4be4-835c-338431977cdc'::uuid, 'e4bbe556-60a6-495d-837a-cb39ca0295d2'::uuid, '디지털 화폐(CBDC)', '중앙은행이 발행하는 디지털 형태의 법정 화폐를 뜻하는 용어는?', 'CBDC(Central Bank Digital Currency)는 중앙은행이 직접 발행하고 관리하는 법정 통화입니다.', '[{"no": 1, "content": "비트코인", "isCorrect": false}, {"no": 2, "content": "이더리움", "isCorrect": false}, {"no": 3, "content": "CBDC", "isCorrect": true}, {"no": 4, "content": "NFT", "isCorrect": false}]'::json, 'FUTURES', '중앙은행 디지털 화폐'),
-- ('20000000-0000-0000-0000-000000000005'::uuid, 'b60e3b88-437f-4be4-835c-338431977cdc'::uuid, '043fddee-890b-4b51-b048-5e05217f5bf9'::uuid, '토큰증권(ST)', '부동산, 미술품 등의 자산을 조각내어 블록체인 기반의 증권 형태로 발행한 것은?', '토큰증권(ST)은 실물 자산을 디지털 증권화하여 소액 투자를 가능하게 합니다.', '[{"no": 1, "content": "가상화폐", "isCorrect": false}, {"no": 2, "content": "토큰증권", "isCorrect": true}, {"no": 3, "content": "스테이블코인", "isCorrect": false}, {"no": 4, "content": "유동화증권", "isCorrect": false}]'::json, 'FUTURES', '토큰증권');

-- -- [DOMESTIC_ETF] 국내 ETF 관련 퀴즈 (5개)
-- INSERT INTO quizzes (quizzes_id, quiz_topics_id, crawled_sources_id, title, question, answer_explanation, choices, main_topic, sub_topic) VALUES 
-- ('30000000-0000-0000-0000-000000000001'::uuid, '577655e3-eb76-45b4-9237-62bb00a617d8'::uuid, '7d3a598c-5ad8-44e3-ad3f-9df83753cf7d'::uuid, 'ETF 괴리율', 'ETF의 시장 가격과 실제 순자산가치(NAV) 사이의 차이를 나타내는 용어는?', '괴리율이 클수록 현재 ETF가 고평가되었거나 저평가되어 적정 가격에 거래되지 못하고 있음을 의미합니다.', '[{"no": 1, "content": "수익률", "isCorrect": false}, {"no": 2, "content": "괴리율", "isCorrect": true}, {"no": 3, "content": "할인율", "isCorrect": false}, {"no": 4, "content": "변동률", "isCorrect": false}]'::json, 'DOMESTIC_ETF', '괴리율'),
-- ('30000000-0000-0000-0000-000000000002'::uuid, '252e4e2b-7419-4064-a2c6-63876fbd9b98'::uuid, '7d3a598c-5ad8-44e3-ad3f-9df83753cf7d'::uuid, '추적오차의 정의', 'ETF가 추종하는 기초지수의 수익률을 얼마나 정확하게 따라가는지 보여주는 지표는?', '추적오차가 작을수록 운용사가 지수를 잘 추종하고 있다는 의미입니다.', '[{"no": 1, "content": "상관관계", "isCorrect": false}, {"no": 2, "content": "추적오차", "isCorrect": true}, {"no": 3, "content": "표준오차", "isCorrect": false}, {"no": 4, "content": "평균오차", "isCorrect": false}]'::json, 'DOMESTIC_ETF', '추적오차'),
-- ('30000000-0000-0000-0000-000000000003'::uuid, '1dde4de1-9f93-4555-8227-cb09b4f9ff6e'::uuid, '7d3a598c-5ad8-44e3-ad3f-9df83753cf7d'::uuid, '유동성 공급자(LP)', 'ETF 시장에서 매수/매도 호가를 지속적으로 제시하여 거래를 활성화하는 주체는?', 'LP(Liquidity Provider)는 투자자가 원활하게 매매할 수 있도록 돕는 금융기관입니다.', '[{"no": 1, "content": "개인투자자", "isCorrect": false}, {"no": 2, "content": "유동성공급자", "isCorrect": true}, {"no": 3, "content": "자산운용사", "isCorrect": false}, {"no": 4, "content": "금융감독원", "isCorrect": false}]'::json, 'DOMESTIC_ETF', '유동성공급자'),
-- ('30000000-0000-0000-0000-000000000004'::uuid, '2ab09aaf-d15c-43f9-80e2-c38b3b3073f7'::uuid, '7d3a598c-5ad8-44e3-ad3f-9df83753cf7d'::uuid, '환노출형 ETF', '기초자산이 해외 자산인 경우, 환율 변동의 영향을 고스란히 받는 상품은?', '환노출형은 수익률에 자산 가격 변동과 환율 변동이 동시에 반영됩니다.', '[{"no": 1, "content": "환헤지형", "isCorrect": false}, {"no": 2, "content": "환노출형", "isCorrect": true}, {"no": 3, "content": "환고정형", "isCorrect": false}, {"no": 4, "content": "환중립형", "isCorrect": false}]'::json, 'DOMESTIC_ETF', '환노출형'),
-- ('30000000-0000-0000-0000-000000000005'::uuid, 'e596ec51-a6ae-44c1-acb7-ee44cf74ad56'::uuid, '7d3a598c-5ad8-44e3-ad3f-9df83753cf7d'::uuid, '레버리지 ETF', '지수 상승 시 그 수익률의 2배를 추구하도록 설계된 상품의 명칭은?', '레버리지 ETF는 지수 변동 폭을 확대하여 추종하는 고위험 상품입니다.', '[{"no": 1, "content": "인버스 ETF", "isCorrect": false}, {"no": 2, "content": "레버리지 ETF", "isCorrect": true}, {"no": 3, "content": "액티브 ETF", "isCorrect": false}, {"no": 4, "content": "섹터 ETF", "isCorrect": false}]'::json, 'DOMESTIC_ETF', '레버리지효과');

-- -- [BASIC_FINANCE] 기초 금융 상식 관련 퀴즈 (5개)
-- INSERT INTO quizzes (quizzes_id, quiz_topics_id, crawled_sources_id, title, question, answer_explanation, choices, main_topic, sub_topic) VALUES 
-- ('40000000-0000-0000-0000-000000000001'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, 'd32dda28-dfd0-449b-b265-3fb70c01cab5'::uuid, '인플레이션 이해', '물가가 지속적으로 오르면서 화폐의 구매력이 떨어지는 경제 현상을 무엇이라 하는가?', '인플레이션은 물가 상승으로 인해 같은 돈으로 살 수 있는 물건의 양이 줄어드는 것을 말합니다.', '[{"no": 1, "content": "디플레이션", "isCorrect": false}, {"no": 2, "content": "인플레이션", "isCorrect": true}, {"no": 3, "content": "스테그플레이션", "isCorrect": false}, {"no": 4, "content": "리플레이션", "isCorrect": false}]'::json, 'BASIC_FINANCE', '인플레이션'),
-- ('40000000-0000-0000-0000-000000000002'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, '7526e92c-2f13-4656-8ae1-5b6689ea4790'::uuid, '복리의 원리', '원금에 대해서만 이자가 붙는 단리와 달리, 발생한 이자에도 이자가 붙는 방식은?', '복리(Compound Interest)는 시간이 갈수록 자산이 불어나는 속도가 가속화되는 특징이 있습니다.', '[{"no": 1, "content": "단리", "isCorrect": false}, {"no": 2, "content": "복리", "isCorrect": true}, {"no": 3, "content": "고정금리", "isCorrect": false}, {"no": 4, "content": "변동금리", "isCorrect": false}]'::json, 'BASIC_FINANCE', '복리'),
-- ('40000000-0000-0000-0000-000000000003'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, '4f676f9c-b0ef-4c33-a0fa-47bfa24825a9'::uuid, '신용등급의 중요성', '개인이나 기업이 빚을 제때 갚을 수 있는 능력을 평가한 지표를 무엇이라 하는가?', '신용점수 또는 신용등급은 금융 거래 시 대출 한도와 금리를 결정하는 핵심 요소입니다.', '[{"no": 1, "content": "재무상태", "isCorrect": false}, {"no": 2, "content": "신용등급", "isCorrect": true}, {"no": 3, "content": "자본비율", "isCorrect": false}, {"no": 4, "content": "유동성비율", "isCorrect": false}]'::json, 'BASIC_FINANCE', '신용등급'),
-- ('40000000-0000-0000-0000-000000000004'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, 'af8ae7fb-f5cb-4ba5-9fd6-84711a7463a2'::uuid, '현금흐름(Cash Flow)', '기업으로 들어오고 나가는 실제 돈의 흐름을 나타내는 말은?', '현금흐름은 장부상 이익보다 기업의 실제 생존 능력을 더 잘 보여주는 지표입니다.', '[{"no": 1, "content": "당기순이익", "isCorrect": false}, {"no": 2, "content": "현금흐름", "isCorrect": true}, {"no": 3, "content": "영업비용", "isCorrect": false}, {"no": 4, "content": "매출액", "isCorrect": false}]'::json, 'BASIC_FINANCE', '현금흐름'),
-- ('40000000-0000-0000-0000-000000000005'::uuid, 'b4ea692f-8819-4904-9504-c67c0e2251de'::uuid, 'f49e4ba7-d5ca-4f21-9365-380b34964f64'::uuid, '자기자본이익률(ROE)', '기업이 투입한 자기자본이 얼마만큼의 이익을 냈는지를 나타내는 지표는?', 'ROE(Return On Equity)는 경영 효율성을 보여주는 대표적인 수익성 지표입니다.', '[{"no": 1, "content": "부채비율", "isCorrect": false}, {"no": 2, "content": "자기자본이익률(ROE)", "isCorrect": true}, {"no": 3, "content": "유동비율", "isCorrect": false}, {"no": 4, "content": "당좌비율", "isCorrect": false}]'::json, 'BASIC_FINANCE', '자기자본이익률');
